package hu.boltseged.admin;
import hu.boltseged.account.*; import hu.boltseged.shipment.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/admin/billing") public class AdminBillingController {final ShipmentRepository repo;AdminBillingController(ShipmentRepository r,AccountRepository a){repo=r;}@GetMapping Page<Row> list(@RequestParam(required=false)UUID accountId,@RequestParam(required=false)String billingStatus,@RequestParam(required=false)String shipmentStatus,@RequestParam(required=false)String tracking,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,Pageable page){return repo.findAll(spec(accountId,billingStatus,shipmentStatus,tracking,from,to),page).map(Row::from);}@GetMapping("/csv")ResponseEntity<byte[]> csv(@RequestParam(required=false)UUID accountId,@RequestParam(required=false)String billingStatus,@RequestParam(required=false)String shipmentStatus,@RequestParam(required=false)String tracking,@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to){StringBuilder b=new StringBuilder("shipment_date,company,master_tracking,package_count,destination_country,dhl_product,dhl_estimated_cost,customer_price,currency,billing_status\n");repo.findAll(spec(accountId,billingStatus,shipmentStatus,tracking,from,to),Sort.by("createdAt")).forEach(s->b.append(s.getShipDate()).append(',').append(csvValue(s.getAccount().getCompanyName())).append(',').append(s.getMasterTrackingNumber()).append(',').append(s.getPackages().size()).append(',').append("\"\"").append(',').append(s.getDhlProductCode()).append(',').append(s.getDhlEstimatedCost()).append(',').append(s.getCustomerPrice()).append(',').append(s.getCurrency()).append(',').append(s.getBillingStatus()).append('\n'));return ResponseEntity.ok().contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=billing.csv").body(("\uFEFF"+b).getBytes(StandardCharsets.UTF_8));}@PostMapping("/invoice")void invoice(@RequestBody List<UUID> ids){repo.findAllById(ids).forEach(s->{if("CREATED".equals(s.getStatus()))s.invoice();});repo.flush();}private Specification<Shipment> spec(UUID a,String bill,String status,String track,LocalDate from,LocalDate to){return(root,q,cb)->{List<jakarta.persistence.criteria.Predicate> p=new ArrayList<>();if(a!=null)p.add(cb.equal(root.get("account").get("id"),a));if(bill!=null)p.add(cb.equal(root.get("billingStatus"),bill));if(status!=null)p.add(cb.equal(root.get("status"),status));if(track!=null&&!track.isBlank())p.add(cb.like(cb.lower(root.get("masterTrackingNumber")),"%"+track.toLowerCase()+"%"));if(from!=null)p.add(cb.greaterThanOrEqualTo(root.get("shipDate"),from));if(to!=null)p.add(cb.lessThanOrEqualTo(root.get("shipDate"),to));return cb.and(p.toArray(new jakarta.persistence.criteria.Predicate[0]));};}private String csvValue(String x){return x==null?"\"\"":"\""+x.replace("\"","\"\"")+"\"";}record Row(UUID id,String company,String masterTrackingNumber,int packageCount,BigDecimal dhlEstimatedCost,BigDecimal customerPrice,String currency,String billingStatus,String status){static Row from(Shipment s){return new Row(s.getId(),s.getAccount().getCompanyName(),s.getMasterTrackingNumber(),s.getPackages().size(),s.getDhlEstimatedCost(),s.getCustomerPrice(),s.getCurrency(),s.getBillingStatus(),s.getStatus());}}}
